SELECT CAST(COUNT(DISTINCT CASE WHEN a.readmit_30d THEN a.stay_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.stay_id), 0) AS readmission_rate, AVG(CASE WHEN a.readmit_30d THEN a.los END) AS avg_los_30d, SUM(CASE WHEN a.readmit_30d THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(DISTINCT a.stay_id), 0) AS pct_stays_30d_or_more FROM (SELECT s.stay_id, s.subject_id, s.hadm_id, s.icustay_id, s.intime, s.outtime, s.los, lag(s.outtime) OVER (PARTITION BY s.subject_id ORDER BY s.intime) AS previous_outtime, lead(s.intime) OVER (PARTITION BY s.subject_id ORDER BY s.intime) AS next_intime, (s.intime - lag(s.outtime) OVER (PARTITION BY s.subject_id ORDER BY s.intime)) AS stay_duration, (s.intime - lag(s.outtime) OVER (PARTITION BY s.subject_id ORDER BY s.intime)) / NULLIF(lead(s.intime) OVER (PARTITION BY s.subject_id ORDER BY s.intime)-s.intime, 0) AS stay_duration_ratio, CASE WHEN (s.intime - lag(s.outtime) OVER (PARTITION BY s.subject_id ORDER BY s.intime)) > 30 THEN 1 ELSE 0 END AS readmit_30d FROM icustays s JOIN patients p ON p.subject_id = s.subject_id WHERE p.gender = 2 AND EXTRACT(YEAR FROM CURRENT_DATE) - p.birth_year >= 66 AND p.insurance = 'Medicare' AND p.anchor_year >= 61 AND p.anchor_year <= 71 AND s.first_careunit = 'SNF' AND s.intime <= s.outtime AND (s.intime - lag(s.outtime) OVER (PARTITION BY s.subject_id ORDER BY s.intime)) <= 30) AS a;